import{_ as a,o as i,c as n,aj as e}from"./chunks/framework.BdtAaXf2.js";const E=JSON.parse('{"title":"34-模式匹配的 Refutability","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/34-模式匹配的Refutability/34-模式匹配的Refutability.md","filePath":"仓颉入门到实战/34-模式匹配的Refutability/34-模式匹配的Refutability.md","lastUpdated":1736065340000,"__rawMarkdown":"# 34-模式匹配的 Refutability\\n\\n模式可以分为两类：`refutable` 模式和 `irrefutable` 模式\\n\\n1. `refutable` `/rɪˈfjuːtəbl/` 不可驳倒的，表示模式**不一定匹配成功**\\n2. `irrefutable` 不可驳倒 ， 表示模式一定成功\\n\\n## 常量模式\\n\\n常量模式是 `refutable` 模式。例如，下例中第一个 case 中的 `1` 和第二个 case 中的 `2` 都有可能和 `x` 的值不相等。\\n\\n```javascript\\nfunc constPat(x: Int64) {\\n    match (x) {\\n        case 1 => \\"one\\"\\n        case 2 => \\"two\\"\\n        case _ => \\"_\\"\\n    }\\n}\\n```\\n\\n## 通配符\\n\\n通配符模式是 `irrefutable` 模式。例如，下例中无论 `x` 的值是多少，`_` 总能和其匹配。\\n\\n```javascript\\nfunc wildcardPat(x: Int64) {\\n    match (x) {\\n        case _ => \\"_\\"\\n    }\\n}\\n```\\n\\n## 绑定模式\\n\\n绑定模式是 `irrefutable` 模式。例如，下例中无论 `x` 的值是多少，绑定模式 `a` 总能和其匹配。\\n\\n```javascript\\nfunc varPat(x: Int64) {\\n    match (x) {\\n        case a => \\"x = ${a}\\"\\n    }\\n}\\n```\\n\\n## Tuple 模式\\n\\nTuple 模式是 `irrefutable` 模式，当且仅当其包含的每个模式都是 `irrefutable` 模式。例如，下例中 `(1, 2)` 和 `(a, 2)` 都\\n\\n有可能和 `x` 的值不匹配，所以它们是 `refutable` 模式，而 `(a, b)` 可以匹配任何 `x` 的值，所以它是 `irrefutable` 模式。\\n\\n```javascript\\nfunc tuplePat(x: (Int64, Int64)) {\\n    match (x) {\\n        case (1, 2) => \\"(1, 2)\\"\\n        case (a, 2) => \\"(${a}, 2)\\"\\n        case (a, b) => \\"(${a}, ${b})\\"\\n    }\\n}\\n```\\n\\n## 类型模式\\n\\n类型模式是 `refutable` 模式。例如，下例中（假设 `Base` 是 `Derived` 的父类，并且 `Base` 实现了接口 `I`），`x` 的运行时类\\n\\n型有可能既不是 `Base` 也不是 `Derived`，所以 `a: Derived` 和 `b: Base` 均是 `refutable` 模式。\\n\\n```javascript\\ninterface I {}\\nopen class Base <: I {}\\nclass Derived <: Base {}\\n\\nfunc typePat(x: I) {\\n    match (x) {\\n        case a: Derived => \\"Derived\\"\\n        case b: Base => \\"Base\\"\\n        case _ => \\"Other\\"\\n    }\\n}\\n```\\n\\n## enum 模式\\n\\nenum 模式是 `irrefutable` 模式，当且仅当它对应的 `enum` 类型中只有一个有参构造器，且 enum 模式中包含的其他模式也是\\n\\n`irrefutable` 模式。例如，对于下例中的 `E1` 和 `E2` 定义，函数 `enumPat1` 中的 `A(1)` 是 `refutable` 模\\n\\n式，`A(a)` 是 `irrefutable` 模式；而函数 `enumPat2` 中的 `B(b)` 和 `C(c)` 均是 `refutable` 模式。\\n\\n```javascript\\nenum E1 {\\n    A(Int64)\\n}\\n\\nenum E2 {\\n    B(Int64) | C(Int64)\\n}\\n\\nfunc enumPat1(x: E1) {\\n    match (x) {\\n        case A(1) => \\"A(1)\\"\\n        case A(a) => \\"A(${a})\\"\\n    }\\n}\\n\\nfunc enumPat2(x: E2) {\\n    match (x) {\\n        case B(b) => \\"B(${b})\\"\\n        case C(c) => \\"C(${c})\\"\\n    }\\n}\\n```\\n"}'),l={name:"仓颉入门到实战/34-模式匹配的Refutability/34-模式匹配的Refutability.md"};function p(t,s,h,k,r,d){return i(),n("div",null,[...s[0]||(s[0]=[e("",25)])])}const u=a(l,[["render",p]]);export{E as __pageData,u as default};
